import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const m=JSON.parse('{"title":"第02章 跟着我","description":"","frontmatter":{},"headers":[],"relativePath":"第02章_跟着我.md","filePath":"第02章_跟着我.md"}'),o={name:"第02章_跟着我.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第02章-跟着我" tabindex="-1">第02章 跟着我 <a class="header-anchor" href="#第02章-跟着我" aria-label="Permalink to &quot;第02章 跟着我&quot;">​</a></h1><p>她拉我进那款游戏，是在一个下雨的下午。</p><p>南雾县一下雨就没什么可干的，路是土路，出门踩一脚泥，回来要刷半小时鞋。我趴在阳台的栏杆上看雨，看桥头那盏灯在水里碎成一堆亮片。</p><p>她说：你下个游戏吧。</p><p>我说：我不玩游戏。</p><p>她说：那你现在开始玩。</p><p>我说：为什么。</p><p>她说：因为我玩。</p><p>我就去下了。那款游戏很大，我家的网很慢，装了一下午。她在那边每隔一会儿问一句，好了没。我说没。她说，你家的网是纸做的吗。</p><p>我说，差不多。</p><p>她说，那你今天别想玩了。</p><p>我说，那我明天再玩。</p><p>她说，明天就来不及了。</p><p>我问，来不及什么。</p><p>她没答，过了一会儿说，你先下，下好了叫我。</p><p>我把手机放在桌上，看着进度条一截一截往前爬。爬到一半的时候卡住了，不动。我把路由器拔了重插，等它重新连上，进度条又慢慢地走。奶奶从厨房出来，问我趴在那里干什么。我说下个东西。她说，下什么东西要下这么久。我答不上来。</p><p>天阴着，五点多就暗了。我把屋里的灯开了，泡了一碗面，边吃边守着屏幕。</p><p>那会儿她也在等。她给我发她屋里的事：她妹妹在看电视，声音开得很大；她妈在厨房收拾，把锅磕得咔咔响；她自己靠在一张小桌子上写作业，写完一页就抬头看我回没回。</p><p>我问，你家里没人管你看手机吗。</p><p>她说，管。</p><p>我说，那你还玩。</p><p>她说，趁他们不注意。</p><p>我说，那不就得删记录。</p><p>她说，你不懂。她又发一条：我比你懂。</p><p>我那时候真不懂。我只觉得她挺大胆。后来我才知道，那不是大胆，那是习惯。一件事你要每次都小心，时间长了就不叫小心了，那就叫日子。</p><p>装好已经是傍晚。她让我建号，取名字。我想了半天，取了一个很正经的名字。她说，土。</p><p>我说：那你给我取。</p><p>她说：不取，你自己想，想不出来别玩了。</p><p>我改了三次。第三次她勉强同意，说，凑合吧。</p><p>进游戏，她已经在里面等我了。她的角色比我大好几级，走路带风。她说，跟着我。</p><p>我跟着她。走到第一处水边，我掉下去了。</p><p>她说，你往哪走呢。</p><p>我说，我不知道怎么停。</p><p>她说，按那个键，你手呢。</p><p>我说，我按了。</p><p>她说，你按的是哪只。</p><p>我说，左手。</p><p>她说，你换右手。</p><p>我换了，爬上来，走了三步又掉下去。</p><p>她在那边笑了一长串，笑得我耳朵发烫。笑完她说，你站着别动，我回来接你。</p><p>我说，那你也掉下来怎么办。</p><p>她说，我掉下来我们就一起死。</p><p>我说，那不行。</p><p>她说，那你就别动。</p><p>她的角色从远处跑回来，站在岸边，转了个圈。她说，看准我脚下，走我走过的地方。</p><p>我就跟着她的脚印走。她走得慢，一步一步，像在等我。走到一半她停下来，说，你踩到草了。我说草怎么了。她说，草会记住的。</p><p>我说，游戏里哪来的草会记住。</p><p>她说，我说会就会。</p><p>过了水，她带我往山上走。路上她捡了一堆东西，边走边丢，丢完再捡。我问她在干什么。她说，攒着，以后有用。我说有什么用。她说，到时候你就知道了。</p><p>她说什么都是这样。她从来不一次把话说完，总要留半截，让你自己去想。我那时候以为那是她的性格。后来我发现，她只是习惯了不把话说满。</p><p>那天晚上我们玩到很晚。她带我去看她的家，是游戏里的一块地，她在上面盖了房子，房子歪歪扭扭，墙没对齐，屋顶还是漏的。她说，你别笑。我说我没笑。</p><p>她说，你心里笑了。</p><p>她让我在她家旁边也盖一间。我说我不会盖。她说，很简单的，你先放一块地基。我放了，放歪了，跟她的房子错开半个身位，中间空出一条缝。</p><p>她说，你盖得歪。</p><p>我说，那怎么办。</p><p>她说，算了。</p><p>她把那间房子改成小一点的，往我这边挪了挪，正好把那条缝填上。两块地基贴在一起，像两枚齿咬住的梳子。</p><p>我问她，这样算谁家。</p><p>她说，算我们家的。</p><p>我问她，你这块地是什么时候盖的。</p><p>她说，很早。</p><p>我说，多早。</p><p>她说，我一个人的时候。</p><p>她说这句话的时候语气很平，像在说今天吃了什么。我没接话。我那时候不懂&quot;一个人的时候&quot;是什么意思，只觉得这几个字有点沉。</p><p>我又问了一句，那你建这块地的时候，是几年级。</p><p>她想了想，说，初一。</p><p>我说，初一你就玩这个。</p><p>她说，初一的时候我谁都不认识。</p><p>我说，那现在呢。</p><p>她说，现在认识你了。</p><p>她带我绕着她的房子走了一圈。院子边上放着几个箱子，箱子盖着，看不出里面是什么。我问能不能打开。她说，不能。我说，锁了吗。她说，没锁，但是不能打开。</p><p>我说，那为什么。</p><p>她说，有些东西开过一次就旧了。</p><p>那天她的头像黑下去之后，我在那块地上坐到很晚。游戏里有昼夜，天黑了，她家屋顶的破洞里能看见星星。我试着跳了一下，跳不上去，就原地坐着。</p><p>我那时候还不知道自己在做什么。我只是觉得，屏幕上有这么一块地方，两个歪歪的房子拼在一起，中间那条缝是她挪过来填上的。</p><p>后来我才明白，那是我第一次想让一件事长久一点。</p><p>那晚临睡前，她发来一条：以后你就跟着我。</p><p>我回：好。</p><p>她又发：你要是自己乱跑，我就不带你了。</p><p>我说：我不乱跑。</p><p>她说：记住你今天说的。</p><p>我记住了。我也真的没乱跑。我后来几年的很多选择，都是在那天晚上定的：跟着她，等她，别乱走。</p><p>我以为那是一种忠诚。很久以后我才知道，一个人不肯走开，有时候只是因为不敢往别的地方看。</p><p>第二天早上，她说她要去补作业了，要消失几天。</p><p>我说好。</p><p>她说：你会无聊吗。</p><p>我说，不会。</p><p>她说：骗人。</p><p>然后她发来一张图，是她那间歪房子的截图，屋顶的破洞里，有一颗很亮的星星。</p><p>她说：给你了。</p>',90)])])}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
